def calculate_minimum_hp(d):
    R_, C = len(d), len(d[0]); INF = float("inf"); need = [[INF] * (C + 1) for _ in range(R_ + 1)]; need[R_][C - 1] = need[R_ - 1][C] = 1
    for i in range(R_ - 1, -1, -1):
        for j in range(C - 1, -1, -1):
            need[i][j] = max(1, min(need[i + 1][j], need[i][j + 1]) - d[i][j])
    return need[0][0]

