int calculateMinimumHP(vector<vector<int>>& d) {
    int R = d.size(), C = d[0].size(); vector<vector<long long>> need(R + 1, vector<long long>(C + 1, LLONG_MAX)); need[R][C-1] = need[R-1][C] = 1;
    for (int i = R - 1; i >= 0; i--) for (int j = C - 1; j >= 0; j--) need[i][j] = max(1LL, min(need[i+1][j], need[i][j+1]) - d[i][j]);
    return (int)need[0][0];
}
